{"query": "
SELECT w.date, w.type, w.category, w.duration_min, w.hr_avg, w.gpx_distance_km, w.gpx_elevation_gain_m
FROM workout_all w
WHERE w.date BETWEEN '2026-08-03' AND '2026-08-06'
ORDER BY w.date;
"}

{"query": "
SELECT date, hrv_ms, resting_hr, recovery_index, vo2max
FROM daily
WHERE date BETWEEN '2026-08-03' AND '2026-08-06'
ORDER BY date;
"}

{"query": "
SELECT date, sleep_total_h, sleep_efficiency_pct, sleep_deep_h, sleep_core_h, sleep_rem_h, sleep_awake_h, source
FROM sleep_all
WHERE date BETWEEN '2026-08-03' AND '2026-08-06'
ORDER BY date;
"}
